   'deep',
   '{"summary":"Reject alg=none JWTs and enforce signature verification server-side.","steps":["Allowlist permitted JWT algorithms and reject alg=none before parsing claims.","Gate /api/jwt/decode behind authenticated lab sessions.","Never decode attacker-supplied tokens without signature verification."]}'::jsonb,
   'Our /api/jwt/decode accepts alg=none tokens without signature validation. Show secure JWT verification patterns.',
   true),
  ('vulnlab-platform-aspnet-live-oracle', 'generic', 'Security misconfiguration', 'high',
